exec('import csv,os,requests\nactive=set(x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip())\nrows=[r for r in csv.DictReader(open("signals_history.csv",encoding="utf-8")) if r["ticker"] in active]\nlatest_by_ticker={}\nfor r in rows:\n if r["ticker"] not in latest_by_ticker or r["date"]>latest_by_ticker[r["ticker"]]["date"]: latest_by_ticker[r["ticker"]]=r\nselected=[r for r in latest_by_ticker.values() if r["signal"] in ("ACHAT","SURCHAUFFE","SURVEILLANCE HAUTE","FAIBLESSE FORTE")]\nselected.sort(key=lambda r:(r["date"],int(r["score"])),reverse=True)\nlines=["INVESTMENT ASSISTANT","Derniere cloture disponible pour chaque marche",""]\nfor r in selected:\n devise="EUR" if r["ticker"].endswith((".PA",".AS")) else "USD"\n lines.append(r["signal"]+" | "+r["ticker"]+" | Date : "+r["date"]+" | Cloture J-1 : "+r["price"]+" "+devise+" | Score "+r["score"]+"/100 | Var5j "+r["var5"]+"% | RSI "+r["rsi14"]+" | RVOL "+r["rvol"])\nif not selected: lines.append("Aucun signal prioritaire.")\nlines.extend(["","Analyse basee sur la derniere cloture disponible.","Signaux experimentaux en paper trading. Aucun ordre reel."])\nmessage="\\n\\n".join(lines)\nr=requests.post("https://api.telegram.org/bot"+os.environ["TELEGRAM_BOT_TOKEN"]+"/sendMessage",data={"chat_id":os.environ["TELEGRAM_CHAT_ID"],"text":message},timeout=30)\nprint("Telegram alert:",r.status_code,r.json().get("ok"))')
